  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Donepezil, a lipophilic basic amine with an indanone/piperidine scaffold, has essentially complete oral bioavailability (~100%) in humans, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Urapidil, which contains multiple basic nitrogens and aromatic rings, has an absolute oral bioavailability of 78% (72-84%) in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Diphenhydramine, a lipophilic tertiary-amine drug, has absolute oral bioavailability of 42±5% in elderly subjects and 35-72% across studies, all above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Imipramine-N-oxide, a charged amine-oxide tricyclic, showed ~100% oral systemic availability, demonstrating that ionization does not preclude high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Moexipril, the lowest analogue at 22% oral bioavailability, still exceeds the 20% threshold, providing a lower-bound supportive anchor.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability above 20%, most well above it, and none support F<20%. The query's basic amine/indane scaffold is consistent with these high-bioavailability drugs, so the prediction is high.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule.",
    "No exact analogue with the same dicationic diamine/indane scaffold was available.",
    "First-pass metabolism and transporter-mediated absorption for the query are unmeasured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

